cssCode:
.smoke-text {
  font-size: 60px; font-weight: 900; font-family: sans-serif;
  color: transparent; text-transform: uppercase;
  text-shadow: 0 0 30px rgba(255, 255, 255, 1);
  transition: text-shadow 0.8s ease-out, color 0.8s ease-out;
  cursor: pointer; letter-spacing: 5px;
}
.smoke-text:hover {
  color: #ffffff;
  text-shadow: 0 0 0px rgba(255, 255, 255, 0);
}

